-- Producción histórica previa a la app (2026-05-22 a 2026-08-29), tomada de
-- Control.xlsx y Base_de_datos_produccion.xlsx (Excel/KARDEX que llevaba
-- planta antes de este módulo). Estadísticas no tiene cómo calcular "kg
-- producidos/empacados" para esas fechas (no existían baches/envasados
-- todavía) -- esta tabla guarda el total diario ya consolidado para que el
-- histórico de Estadísticas se pueda extender hacia atrás en vez de
-- arrancar vacío en septiembre 2026.
--
-- produccion/empaque quedan en jsonb con el desglose por referencia tal
-- como venía del Excel (no se intenta mapear a product_id/referencia_id
-- actuales -- los nombres de esa época no necesariamente calzan 1:1 con el
-- catálogo de hoy). Estadísticas solo usa kilos_producidos/kilos_empacados
-- para el total del mes; el desglose queda guardado por si hace falta
-- auditar un día puntual.
create table produccion_historica (
  id uuid primary key default gen_random_uuid(),
  fecha date not null unique,
  lote integer,
  kilos_producidos numeric(12, 2) not null default 0,
  kilos_empacados numeric(12, 2) not null default 0,
  produccion jsonb not null default '[]'::jsonb,
  empaque jsonb not null default '[]'::jsonb,
  fuente text,
  observaciones text,
  created_at timestamptz not null default now()
);

alter table produccion_historica enable row level security;
create policy "produccion_historica_select" on produccion_historica
  for select to authenticated
  using (is_staff() or current_role_is('asistente_adm') or current_role_is('planeacion'));
create policy "produccion_historica_insert" on produccion_historica
  for insert to authenticated with check (current_role_is('jefe_planta'));
create policy "produccion_historica_update" on produccion_historica
  for update to authenticated using (current_role_is('jefe_planta'));
create policy "produccion_historica_delete" on produccion_historica
  for delete to authenticated using (current_role_is('jefe_planta'));

create index idx_produccion_historica_fecha on produccion_historica(fecha);

on conflict (fecha) do nothing;
